# content_illd.py — ILLD International Journal of Legal Medicine Original article 원고의 Methods·Results 문장(수치는 numbers_illd에서만, 2026-11-16).
#  IJLM 규칙: 초록 150–250, 키워드 4–6, 대괄호 숫자 인용, 보충은 Online Resource, 패널 문자 소문자, SAGER(성·연령 분해), 국명 Republic of Korea.
#  단독 저자 → 1인칭 금지. 결과 절에 해석 금지. 제목 쌍점 금지. 역방향(응급의학 전문의)은 post hoc 표기, 주모형 교체 금지. between 비credible이면 'between districts' 주장 금지.
from numbers_illd import load, ROB, EM, LTC, BLS, TE, MPA, GH, IM, UN, ALN, DR, WALK, FAC, VIL, KH
N = load()
def b(x): return f"{x:.3f}"
def tci(t, cred=None):   #  저장값 그대로(셋째 자리). 경계 1.000인 credible 구간은 문장에서 사후확률로 설명(11/13 review)
    lo, hi = b(t[1]), b(t[2]); cr = t[3] if len(t) > 3 else cred
    return f"RR: {t[0]:.3f}; 95% CrI: {lo}–{hi}"
def ci(v): r = N["main"][v]; return tci((r["IRR"], r["lo"], r["hi"], bool(r["cred"])))
M = N["main"]; T1 = N["T1"]; S = N["sub"]; SX = N["sexsub"]
S43 = lambda a, v: N["s43"][(a, v)]
BW = lambda v, p: N["bw"][f"{v}__{p}"]
NCO = lambda o, v: N["nco"][(o, v)]
MV = lambda v: (int(N["mv"][v]["n_specs"]), N["mv"][v]["cred_frac"])
WN = ("W1_2011-15", "W2_2016-19", "W3_2020-24")
wt = lambda v, w: N["win"][(v, w)]
EN = {"서울시": "Seoul", "충청남도": "Chungcheongnam-do", "경기도": "Gyeonggi-do", "전라남도": "Jeollanam-do", "전라북도": "Jeollabuk-do", "충청북도": "Chungcheongbuk-do", "부산시": "Busan", "경상남도": "Gyeongsangnam-do",
      "강원도": "Gangwon-do", "대전시": "Daejeon", "경상북도": "Gyeongsangbuk-do", "울산시": "Ulsan"}
def sidos(d, n):
    l = [f"{EN[k]} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
TITLE = "Ill-defined causes in Korean death certification vary inversely with circulatory deaths and with long-term care hospital supply"
RUNNING = "Ill-defined death certification in Korea"
KEYWORDS = "Death certificates; Cause of death; Death investigation; Ill-defined causes; Long-term care hospitals; Small-area analysis"
assert ":" not in TITLE and len(TITLE.split()) <= 20 and "229" not in TITLE and "tandardi" not in TITLE and 4 <= len(KEYWORDS.split("; ")) <= 6
SUP = {"methods": "Online Resource 1, Appendix A", "substitution": "Online Resource 1, Table S1", "covariates": "Online Resource 1, Table S2", "datacheck": "Online Resource 1, Table S3", "specs": "Online Resource 1, Table S4", "strobe": "Online Resource 1, Appendix B"}   # 첫 인용 순서
sup = lambda k: SUP[k]
AG = N["agesex"]; ASR = N["asr"]
ALT = len(N["alt"]); RET = N["ret"]

METHODS = [
("Study design and data",
 f"This ecological study covered all {N['n_districts']} districts (urban wards, cities and counties) of the Republic of Korea, harmonised to 2024 boundaries, over 2011–2024 ({N['n_rows']:,} district-years), and is reported according to the Strengthening the Reporting of Observational Studies in Epidemiology (STROBE) and the Reporting of studies Conducted using Observational Routinely-collected health Data (RECORD) statements [@vonelm2007strengthening; @benchimol2015reporting]. Annual deaths by underlying cause (International Classification of Diseases, 10th revision; ICD-10), sex, 5-year age group and district of residence came from the national cause-of-death statistics, which include all registered deaths [@web:kostat2026cause], and resident populations by sex and age from resident registration [@web:mois2026population] ({sup('methods')}). Districts were joined across sources by administrative code only, and the completed checklist is in {sup('strobe')}."),
("Outcome and expected deaths",
 "The outcome was deaths whose underlying cause was in ICD-10 Chapter XVIII (symptoms, signs and abnormal clinical and laboratory findings not elsewhere classified, R00–R99), which includes senility (R54), sudden death (R96), unattended death (R98) and unknown cause (R99); deaths of undetermined intent (Y10–Y34) are external causes and were not included. The published district tables give only the chapter total, and record-level data were not used. Expected deaths were obtained by indirect standardisation, applying national death rates for this chapter by year, sex and eighteen age groups (5-year groups to 80–84 years and 85 years or older) to each district population and rescaling so that national expected deaths equalled observed deaths each year [@inskip1983methods]; the observed-to-expected ratio is the standardised mortality ratio (SMR)."),
("Substitution analysis",
 f"Before models were fitted, the analysis plan specified tests of whether districts that certify more deaths as ill-defined record fewer deaths from specific causes ({sup('substitution')}). For circulatory diseases (I00–I99), ischaemic heart disease (I20–I25), cerebrovascular disease (I60–I69), Alzheimer disease (G30), pneumonia (J12–J18) and malignant neoplasms (C00–C97) as a comparator, the following were computed from SMRs standardised for age (and from sex-specific SMRs in the analyses by sex): the Spearman correlation of 14-year district SMRs and of shares of all deaths; the variance of log SMRs for the specific cause alone and for the cause combined with ill-defined deaths, compared with 999 random pairings of districts (which ignore spatial autocorrelation, so the resulting P value is descriptive); the correlation of changes in log SMR between 2011–2015 and 2016–2019 and between 2011–2015 and 2020–2024; and the correlation of within-district yearly deviations. Analyses were repeated by sex with sex-specific expected deaths. National age-standardised rates (2015 population) of ill-defined and circulatory deaths were compared, because district comparisons cannot detect a reclassification that is uniform across the country."),
("District characteristics",
 f"Thirteen characteristics were selected a priori from the literature on certification and on senility, with an expected direction for each ({sup('covariates')}). Access to diagnosis and certification was represented by general hospitals, emergency medicine specialists and internal medicine specialists per 100,000 residents, long-term care hospitals per 100,000 residents aged 65 years or older (all expected to lower ill-defined deaths) and unmet health-care need (expected to raise them). Social conditions were represented by the shares of older-adult single-person households, basic livelihood security recipients and high-risk drinkers (expected to raise ill-defined deaths) and of tertiary-educated adults (expected to lower them). Because senility (R54) is a frailty-related certificate entry and physical activity lowers frailty risk [@clegg2013frailty; @zhao2022effect], indicators of physical activity were included as markers of population frailty rather than of certification: age-standardised rates of walking and of moderate-or-higher physical activity from the Community Health Survey [@kang2015korea] and public and village sports facilities per 100,000 residents were expected to lower ill-defined deaths. Five controls were forced into the principal model and every covariate-subset model (one was omitted in a sensitivity analysis): urban population share, physicians per 1,000 residents, sex ratio, fiscal autonomy and the share aged 80 years or older. Covariates were standardised to mean 0 and standard deviation (SD) 1, and panel checks were run before any model was fitted ({sup('datacheck')})."),
("Statistical analysis",
 f"Models were negative binomial, which had a lower widely applicable information criterion (WAIC) than Poisson ({N['waic_nb']:,.0f} versus {N['waic_pois']:,.0f}), with an offset of log expected deaths, a Besag–York–Mollié 2 district effect with penalised-complexity priors [@besag1991bayesian; @riebler2016intuitive; @simpson2017penalising] and random-walk and independent year effects, fitted by integrated nested Laplace approximation in R [@rue2009approximate; @web:rcore2026]. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was called credible when its interval excluded 1. Residual hot spots and cold spots were districts whose posterior probability of a residual spatial RR above 1 exceeded 0.95 or fell below 0.05; this classification was exploratory and not adjusted for multiple comparisons. The principal model was specified before fitting, and space-time interaction models were compared with it by WAIC.",
 f"Robustness was assessed in 200 models with random covariate subsets (an association was called robust when credible in at least 75% of the models containing it with at least 95% sign agreement) [@steegen2016increasing]; four Knorr-Held space-time interactions [@knorrheld2000bayesian]; refits in 2011–2015, 2016–2019 and 2020–2024; district-mean (between-district) and deviation (within-district) components entered together [@bell2015explaining]; {ALT} alternative specifications of likelihood, temporal structure, lags, spatial structure and spatial confounding [@dupont2022spatial]; refits leaving out each province and each year; and alternative neighbour graphs, age standardisation and forced controls. Hit-and-run collisions, fires and the household waste recycling rate were negative control exposures [@lipsitch2010negative]; circulatory and transport-injury deaths, analysed with the same model, were comparison outcomes, and E-values were calculated [@vanderweele2017sensitivity]. Associations against the expected direction were examined post hoc against the certification literature and the comparison-outcome fits."),
("Ethics",
 "Only published aggregate statistics were used, and no individual could be identified. The Institutional Review Board of Hongik University approved the study on 4 November 2025 (7002340-202511-HR-012) and its continuing review on 3 November 2026 (7002340-202611-HR-040) and waived informed consent."),
]

SH = N["share"]; CI_, IH, ST, CA, AL, PN = S["CIRC"], S["IHD"], S["STRK"], S["CANM"], N["sub"].get("ALZ"), N["sub"].get("PNEU")
RESULTS = [
("Ill-defined deaths by year, sex and age",
 f"Of {N['all_total']:,} deaths in 2011–2024, {N['cases_total']:,} ({100*N['cases_total']/N['all_total']:.1f}%) had an ill-defined underlying cause (Table 1). The share was {SH[2011]:.1f}% in 2011, {SH[2015]:.1f}% in 2015 and {SH[2024]:.1f}% in 2024 (Fig. 1). It was higher in women ({AG[(2024, '여자', 'all')]:.1f}% in 2024) than in men ({AG[(2024, '남자', 'all')]:.1f}%) and highest at 85 years or older ({AG[(2011, '계', '85+')]:.1f}% in 2011 and {AG[(2024, '계', '85+')]:.1f}% in 2024); in each age group under 85 years it rose between 2011 and 2024. The national age-standardised rate of ill-defined deaths was {ASR[2011]['ILLD']:.1f} per 100,000 in 2011, {ASR[2019]['ILLD']:.1f} in 2019 and {ASR[2024]['ILLD']:.1f} in 2024, and that of circulatory deaths {ASR[2011]['CIRC']:.1f}, {ASR[2019]['CIRC']:.1f} and {ASR[2024]['CIRC']:.1f}."),
("Geography and substitution",
 f"Ill-defined deaths clustered (Moran's I {N['moran_pooled']:.2f} for pooled log SMRs; spatially structured fraction of the district effect {N['phi'][0]:.2f}, 95% CrI: {N['phi'][1]:.2f}–{N['phi'][2]:.2f}), and district ranks persisted over time (Kendall's W {N['kendall_W']:.2f}). After adjustment, {N['n_hot']} districts were exploratory residual hot spots, most in {sidos(N['hot_by_sido'], 3)}, and {N['n_cold']} were cold spots, most in {sidos(N['cold_by_sido'], 2)} (observed SMRs in Fig. 2).",
 f"District SMRs for ill-defined and circulatory deaths were inversely correlated (Spearman's ρ {CI_['rho_SMR']:.2f}; shares of all deaths, ρ {CI_['rho_share']:.2f}). The variance of log SMRs was {CI_['var_log_SMR_cause']:.4f} for circulatory deaths alone and {CI_['var_log_SMR_combined']:.4f} when ill-defined deaths were added, against a median of {CI_['var_combined_random_median']:.4f} for random pairings (P = {CI_['p_combined_smaller']:.3f}); the ratio of the 90th to the 10th percentile fell from {CI_['P90P10_cause']:.2f} to {CI_['P90P10_combined']:.2f} and Moran's I from {CI_['moran_cause']:.2f} to {CI_['moran_combined']:.2f} (Table 2; Fig. 2). Changes in log SMR were inversely correlated between 2011–2015 and 2016–2019 (ρ {N['sub_pre'][('W1_W2_precovid', 'CIRC')][0]:.2f}) and between 2011–2015 and 2020–2024 (ρ {N['sub_pre'][('W1_W3', 'CIRC')][0]:.2f}), as were within-district yearly deviations (r {N['subw']['CIRC']['r_within_year_dev']:.2f}). The inverse correlation was present for ischaemic heart disease (ρ {IH['rho_SMR']:.2f}), cerebrovascular disease (ρ {ST['rho_SMR']:.2f}, although its combined variance, {ST['var_log_SMR_combined']:.4f}, exceeded that of cerebrovascular deaths alone, {ST['var_log_SMR_cause']:.4f}) and Alzheimer disease (ρ {AL['rho_SMR']:.2f}) but weak for malignant neoplasms (ρ {CA['rho_SMR']:.2f}, with a combined variance larger than that for neoplasms alone, though smaller than for random pairings, P = {CA['p_combined_smaller']:.3f}) and positive for pneumonia (ρ {PN['rho_SMR']:.2f}). It was present in men (ρ {SX['남자']['rho_SMR']:.2f}; combined variance P = {SX['남자']['p_combined_smaller']:.3f}) and women (ρ {SX['여자']['rho_SMR']:.2f}; P = {SX['여자']['p_combined_smaller']:.3f}), and male and female SMRs for ill-defined deaths were correlated (ρ {N['rho_mf']:.2f}) ({sup('substitution')})."),
("District characteristics",
 f"Adding the 13 characteristics lowered the WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f} (Table 3). Ill-defined deaths were lower with more long-term care hospitals ({ci(LTC)}), a higher tertiary-educated share ({ci(TE)}) and more moderate-or-higher physical activity ({ci(MPA)}), and higher with more basic livelihood recipients ({ci(BLS)}) and, against the expected direction, more emergency medicine specialists ({ci(EM)}). General hospitals, internal medicine specialists, unmet need, older-adult single-person households, high-risk drinking, walking and sports facilities had intervals including 1. Of the negative control exposures, the recycling rate had a credible association ({tci(N['negctl']['waste_recycling_rate'])}) and hit-and-run collisions and fires did not. Residual Moran's I was {N['moran_resid']:.2f} (P = {N['moran_resid_p']:.2f}).",
 f"All five associations were credible in every covariate-subset model containing them and in the four sensitivity versions with a queen contiguity graph, age-only or ten-group expected deaths, or without the share aged 80 years or older. Long-term care hospitals remained credible in each Knorr-Held model (type IV, the best-fitting, {tci(S43('KH_typeIV', LTC))}) and in {RET[LTC][0]} of {RET[LTC][1]} alternative specifications, through the within-district component ({tci(BW(LTC, 'within'))}; between, {tci(BW(LTC, 'between'))}). The tertiary-educated share remained credible in types III and IV and in all alternative specifications, through the within-district component ({tci(BW(TE, 'within'))}). Basic livelihood recipients were credible in type II but not types III or IV, and neither component was credible alone. Older-adult single-person households, not credible in the principal model, were credible, against the expected direction, in types II and IV (type IV, {tci(S43('KH_typeIV', ALN))}). Moderate physical activity ({tci(S43('KH_typeIV', MPA))} in type IV) and emergency medicine specialists ({tci(S43('KH_typeIV', EM))}) lost credibility in types II–IV. E-values ranged from {min(N['evalue'][v]['E_point'] for v in ROB):.2f} to {max(N['evalue'][v]['E_point'] for v in ROB):.2f} (Fig. 3; {sup('specs')}).",
 f"For circulatory deaths, the comparison outcome, emergency medicine specialists ({tci(NCO('CIRC', EM))}, posterior probability of an RR above 1 below 0.025) and long-term care hospitals ({tci(NCO('CIRC', LTC))}) were associated in the directions opposite to those for ill-defined deaths, and basic livelihood recipients and physical activity were not associated; the tertiary-educated share was inversely associated with circulatory ({tci(NCO('CIRC', TE))}) and transport-injury deaths ({tci(NCO('TRANS', TE))})."),
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
H = [v for v in M if M[v]["role"] == "hypothesis"]
assert {v for v in H if M[v]["cred"]} == set(ROB) and M[LTC]["IRR"] < 1 and M[TE]["IRR"] < 1 and M[MPA]["IRR"] < 1 and M[BLS]["IRR"] > 1 and M[EM]["IRR"] > 1
assert N["negctl"]["waste_recycling_rate"][3] and not N["negctl"]["hit_and_run_rate"][3] and not N["negctl"]["fires_per_10000"][3]
assert all(N["mv"][v]["cred_frac"] == 1 and N["mv"][v]["sign_agree"] == 1 for v in ROB)
assert all(N["sens"][s][v][3] for s in ("s577", "s2", "s8", "sa") for v in ROB)
assert all(S43(a, LTC)[3] for a in KH) and S43("KH_typeIII", TE)[3] and S43("KH_typeIV", TE)[3] and RET[TE][0] == RET[TE][1]
assert S43("KH_typeII", BLS)[3] and not S43("KH_typeIII", BLS)[3] and not S43("KH_typeIV", BLS)[3] and not BW(BLS, "between")[3] and not BW(BLS, "within")[3]
assert not any(S43(a, v)[3] for a in KH[1:] for v in (MPA, EM))
assert BW(LTC, "within")[3] and not BW(LTC, "between")[3] and BW(TE, "within")[3] and not BW(TE, "between")[3]
assert NCO("CIRC", EM)[3] and NCO("CIRC", EM)[0] < 1 and NCO("CIRC", LTC)[3] and NCO("CIRC", LTC)[0] > 1 and not NCO("CIRC", BLS)[3] and not NCO("CIRC", MPA)[3] and NCO("CIRC", TE)[3] and NCO("TRANS", TE)[3]
assert N["n_hot"] == 91 and N["n_cold"] == 62 and list(N["hot_by_sido"])[:3] == ["서울시", "충청남도", "경기도"]
assert all(AG[(2024, "계", a)] > AG[(2011, "계", a)] for a in ("<45", "45-64", "65-74", "75-84")) and AG[(2024, "계", "85+")] < AG[(2011, "계", "85+")]
assert ST["var_log_SMR_combined"] > ST["var_log_SMR_cause"] and CA["var_log_SMR_combined"] > CA["var_log_SMR_cause"] and S43("KH_typeIV", ALN)[3] and S43("KH_typeII", ALN)[3] and not S43("KH_typeIII", ALN)[3] and not M[ALN]["cred"] and NCO("CIRC", EM)[2] == 1.0
assert PN["rho_SMR"] > 0 and N["sub_pre"][("W1_W2_precovid", "CIRC")][1] < 0.001

if __name__ == "__main__":
    import re
    for x in METHODS + RESULTS: print("##", x[0], "\n", "\n\n".join(x[1:]), "\n")
    print("words M", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for x in METHODS for t in x[1:]), "R", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for x in RESULTS for t in x[1:]))
